#include <stdio.h>

int main(void)
{
    int degree[4]={0},u[]={0,1,2},v[]={1,2,3},sum=0;
    for(int i=0;i<3;i++){degree[u[i]]++;degree[v[i]]++;}
    for(int i=0;i<4;i++){sum+=degree[i];}
    printf("%d\n",sum);
    return 0;
}

